using UnityEngine;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class InspectHud08Scale{public static string Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var a=new JArray();for(var t=h.Sandbox.PauseMenu.Panel.transform;t!=null;t=t.parent)a.Add(new JObject{{"name",t.name},{"local",t.localScale.ToString()},{"world",t.lossyScale.ToString()}});a.Add(new JObject{{"canvas",h.Layout.Canvas.scaleFactor},{"developer",h.Sandbox.PauseMenu.Developer.name},{"panel",h.Sandbox.PauseMenu.Panel.name},{"width",Screen.width}});return a.ToString();}}
